import json
import os
import sys
from pathlib import Path

# Config
source_root = Path('source_masks')
out_root = Path('out')
manifest_path = out_root / 'symlink_manifest.csv'
missing_path = out_root / 'missing_parts.txt'

# Load organ parts
with open('organ_parts.json') as f:
    organ_parts = json.load(f)

# Load splits
splits = {
    'train': open('train.txt').read().strip().split(),
    'val': open('val.txt').read().strip().split(),
    'test': open('test.txt').read().strip().split()
}

# Policy: Priority train > val > test
seen_patients = set()

# Inventory
source_inventory = {}
for p in source_root.rglob('*.nii.gz'):
    patient = p.parent.name
    part = p.name
    source_inventory.setdefault(patient, set()).add(part)

# Classify output
output_state = {}
for split in ['train', 'val', 'test']:
    split_dir = out_root / split
    if not split_dir.exists(): continue
    for item in split_dir.iterdir():
        if item.is_symlink():
            output_state[item] = 'symlink'
        elif item.is_file():
            output_state[item] = 'file'
